                SELECT s."Id", COALESCE(v."Rut", ''), v."Nombres", COALESCE(v."Apellidos", ''), v."Cargo", v."CompaniaExterna",
                    v."Departamento", v."CuentaCorreo", COALESCE(c."Nombre", ''), v."FechaIncorporacion", v."FechaCaducidad",
