                WHERE s."Tipo" = 'VPN' AND s."Estado" = 'Completada' AND v."Nombres" IS NOT NULL
                  AND NOT EXISTS (SELECT 1 FROM "AccesosVpn" a WHERE a."SolicitudId" = s."Id");

